import ToledoLogo from "../../assets/img/experience_and_education/toledo.ico";
import TranDaiNghiaLogo from "../../assets/img/experience_and_education/tran_dai_nghia_high_school.ico";

const educationContent = [
  {
    year: "2025-Present",
    degree: "Master's Degree in Computer Science",
    institute: "The University of Toledo",
    logo: ToledoLogo,
    details: `Anticipated Graduation: May 2027`,
  },
  {
    year: "2018-2022",
    degree: "Bachelor's Degree in Computer Science",
    institute: "The University of Toledo",
    logo: ToledoLogo,
    details: "GPA: 3.674/4.0",
  },
  {
    year: "2015-2018",
    degree: "High School Diploma",
    institute: "Tran Dai Nghia Specialized High school for the Gifted",
    logo: TranDaiNghiaLogo,
    details: "Grade: 9.2 / 10",
  }
];

const Education = () => {
  return (
    <ul>
      {educationContent.map((val, i) => (
        <li key={i}>
          <div className="icon icon-logo">
            <img src={val.logo} alt={`${val.institute} logo`} style={{ width: '100%', height: '100%', objectFit: 'contain' }} />
          </div>
          <span className="time open-sans-font text-uppercase">{val.year}</span>
          <h6 className="poppins-font text-uppercase">
            {val.degree}
            <span className="place open-sans-font">{val.institute}</span>
          </h6>
          <p className="open-sans-font">{val.details}</p>
        </li>
      ))}
    </ul>
  );
};

export default Education;
