import NysusLogo from "../../assets/img/experience_and_education/logo.ico";
import ToledoLogo from "../../assets/img/experience_and_education/toledo.ico";

const experienceContent = [
  {
    year: "Jan 2023 - Dec 2025",
    position: "System Software Developer",
    compnayName: "Nysus Solutions",
    logo: NysusLogo,
    details: `· Maintain and update (mainly web-based) manufacturing software systems related to: just-in-time manufacturing execution
              system (MES), data collection systems, and web-based administrative applications. Many involving integration to PLCs.
              · Work with the Lead Application Architect to design and deploy a robust architecture that will facilitate growth of new
              applications being developed and deployed.
              · Design and integrated MES software with MRP systems and floor equipment (e.g., PLCs, HMIs) to fulfill specific
              manufacturing requirements, facilitating automated production and streamlining information flow.`,
  },
  {
    year: "Jan 2023 - Dec 2025",
    position: "MES Support Analyst",
    compnayName: "Nysus Solutions",
    logo: NysusLogo,
    details: `· Support existing applications using tools developed and MS SQL Server Management Studio.
              · Ensure the reliability and accuracy of all systems implemented at Nysus Solutions.
              · Test troubleshooting methods, devised innovative solutions, and documenting resolutions for inclusion in knowledge base for support team use.
              · Gather data on integration issues and vulnerabilities and reported all findings, including improvement recommendations.`,
  },
  {
    year: "Jan 2021 - Dec 2022",
    position: "System Software Developer Co-op",
    compnayName: "Nysus Solutions",
    logo: NysusLogo,
    details: `· Modified software to fix errors, adapt it to new hardware, improve its performance, or upgrade interfaces.
              · Handled testing and debugging tasks, and perform ongoing troubleshooting.
              · Worked with customers or departments on technical issues including software system design and maintenance.`,
  },
  {
    year: "Jun 2020 - Aug 2020",
    position: "Academic Industry Immersion Seminar",
    compnayName: "The University of Toledo",
    logo: ToledoLogo,
    details: `· Worked on a case study group to develop solutions for Matrix’s Case Study affected by a HAB event while aligning with EPA regulations.
            · Collaborated with team members from the University of Toledo to recommend the most appropriate response to the problem.
            · Completed KEEN Entrepreneurial Mindset Modules about Innovating to Solve Problems Under Organizational Constraints and Learning from Failures.`,
  }
];

const Experience = () => {
  return (
    <ul>
      {experienceContent.map((val, i) => (
        <li key={i}>
          <div className="icon icon-logo">
            <img src={val.logo} alt={`${val.compnayName} logo`} style={{ width: '100%', height: '100%', objectFit: 'contain' }} />
          </div>
          <span className="time open-sans-font text-uppercase">{val.year}</span>
          <h6 className="poppins-font text-uppercase">
            {val.position}
            <span className="place open-sans-font">{val.compnayName}</span>
          </h6>
          <p className="open-sans-font" style={{ whiteSpace: 'pre-line' }}>{val.details}</p>
        </li>
      ))}
    </ul>
  );
};

export default Experience;
