import React from "react";
import Slider from "react-slick";
import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";

const Feedbacks = () => {
  const feedbacksData = [
    {
      id: 1,
      name: "James Knoblauch",
      role: "Senior Software Developer at Nysus Solutions",
      image: "img/feedbacks/james.png",
      feedback:
        `We all love working with Le. Always has a great attitude, and highly motivated. He continues to tackle any task we put in front of him, and has made great progress
        during his co-ops with us, adding value to our team.`
    },
    {
      id: 2,
      name: "Steve Daviduk",
      role: "Senior Software Developer at Nysus Solutions",
      image: "img/feedbacks/steve.png",
      feedback:
        `I had the pleasure of directing Hoang Bao Duy Le on several projects. I was greatly impressed with his enthusiasm, focus and passion to learn the code.
        Hoang Bao Duy Le is quick to learn and willing to put forth the extra effort to complete the tasks. I can see a very bright and successful future ahead.
        We sincerely thank you for your contributions to our team here at Nysus Solutions, LLC.`,
    },
    {
      id: 3,
      name: "Jeff Johnson",
      role: "IT Officer at Toledo Municipal Court",
      image: "img/feedbacks/jeff.png",
      feedback:
        `I've worked with Le for a few months now, and he is terrific to work with. He is quick to get to the bottom and fix issues, is very sharp, and is always in a
        terrific mood. I cannot recommend him highly enough.`,
    },
    {
      id: 4,
      name: "Steve Birdwell",
      role: "Customer Support Manager at Nysus Solutions",
      image: "img/feedbacks/birdwell.png",
      feedback:
        `I really appreciate Bao for his strong work ethic and dedication. He's a hard worker who can always be counted on to get things done well and on time. Bao approaches his work with care and reliability, and it really shows in the quality of what he delivers.
        His positive attitude and commitment make him a great team member, and he's someone you can rely on in any situation. Bao sets a great example through his dedication and the way he approaches his work.`
    },
    {
      id: 5,
      name: "Heysam Salami",
      role: "President of Software Division at Nysus Solutions",
      image: "img/feedbacks/heysam.png",
      feedback:
        `Bao has been a pleasure to work with not only because he consistently completes tasks on time, but because he completes them with great quality.
        He excels at communication, always keeping the team updated on progress, challenges, and and next steps. Bao truly embodies our core values,
        consistently supporting the team and doing whatever it takes to ensure our customers are well served.`,
    }
  ];

  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
    autoplay: true,
    autoplaySpeed: 3000,
    pauseOnHover: true,
    arrows: false,
    responsive: [
      {
        breakpoint: 992,
        settings: {
          slidesToShow: 1,
          slidesToScroll: 1,
        },
      },
    ],
  };

  return (
    <div className="feedbacks-container">
      <Slider {...settings}>
        {feedbacksData.map((feedback) => (
          <div key={feedback.id} className="feedback-item">
            <div className="feedback-card">
              <div className="feedback-bubble">
                <p className="feedback-text">"{feedback.feedback}"</p>
              </div>
              <div className="feedback-author">
                <div className="author-image">
                  <img src={feedback.image} alt={feedback.name} />
                </div>
                <div className="author-info">
                  <h4 className="author-name">{feedback.name}</h4>
                  <p className="author-role">{feedback.role}</p>
                </div>
              </div>
            </div>
          </div>
        ))}
      </Slider>
    </div>
  );
};

export default Feedbacks;
