import React from "react";

const personalInfoContent = [
  { meta: "first name", metaInfo: "Hoang Bao Duy" },
  { meta: "last name", metaInfo: "Le" },
  { meta: "Age", metaInfo: "25 Years" },
  { meta: "Nationality", metaInfo: "Vietnamese" },
  { meta: "Address", metaInfo: "United States" },
  { meta: "phone", metaInfo: "+14196999534" },
  { meta: "Email", metaInfo: "lehoangbaoduy2000@gmail.com" },
  { meta: "langages", metaInfo: "English" },
];

const PersonalInfo = () => {
  return (
    <ul className="about-list list-unstyled open-sans-font">
      {personalInfoContent.map((val, i) => (
        <li key={i}>
          <span className="title">{val.meta}: </span>
          <span className="value d-block d-sm-inline-block d-lg-block d-xl-inline-block">
            {val.metaInfo}
          </span>
        </li>
      ))}
    </ul>
  );
};

export default PersonalInfo;
